<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\ProjectionSettingsService;use App\Services\LiveDisplaySessionService;Auth::requireAdmin();$embed=($_GET['embed']??$_POST['embed']??'')==='1';$pdo=Database::connection();$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$s=$pdo->prepare("SELECT r.*,e.name event_name FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id LIMIT 1");$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Round not found.');}$eventId=(int)$round['event_id'];$settings=ProjectionSettingsService::get($pdo,$roundId,false);$notice=$_SESSION['projection_settings_notice']??'';unset($_SESSION['projection_settings_notice']);if($_SERVER['REQUEST_METHOD']==='POST'&&Csrf::verify($_POST['_csrf']??null)&&($_POST['action']??'')==='generate_live'){LiveDisplaySessionService::generate($pdo,$eventId,false,(int)(Auth::user()['id']??0));$notice='Live Display link generated. Give this one link to the projector operator.';}$session=LiveDisplaySessionService::forEvent($pdo,$eventId,false);$stage=ucfirst((string)$round['round_type']);$types=$round['round_type']==='heats'?['judges'=>'Judges','competitors'=>'Competitors','scoring'=>'Scoring Status','callbacks'=>'Callback Reveal']:($round['round_type']==='semifinal'?['judges'=>'Judges','competitors'=>'Semifinal Competitors','scoring'=>'Scoring Status','finalists'=>'Finalists Reveal']:['judges'=>'Judges','competitors'=>'Finalists / Couples','scoring'=>'Scoring Status','results'=>'Final Ranking','winners'=>'Winner Podium']);$formats=['16:9'=>'16:9 Landscape','9:16'=>'9:16 Portrait','4:3'=>'4:3 Standard','16:10'=>'16:10 Landscape','21:9'=>'21:9 Ultra-wide','32:9'=>'32:9 Super-wide','1:1'=>'1:1 Square','custom'=>'Custom Resolution'];$displayUrl=!empty($session['token_value'])?url('live-display/?token='.rawurlencode((string)$session['token_value'])):'';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Screen Control | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:<?=$embed?'transparent':'#f4f6f9'?>}.card{border:0;border-radius:15px}.settings{border-left:5px solid #dc3545}.embed-main{padding:0!important}.locked{opacity:.55}.status-dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:#198754;margin-right:6px}</style></head><body><?php if(!$embed):?><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">Live Screen Projector</a><a class="btn btn-outline-light btn-sm" href="../scoring/?mode=<?=e((string)($round['scoring_mode']??'manual'))?>&round_id=<?=$roundId?>">Back to Scoring</a></div></nav><?php endif;?><main class="<?=$embed?'embed-main':'container py-4'?>"><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if(!$embed):?><div class="mb-4"><div class="text-uppercase text-danger fw-bold small"><?=e(strtoupper($stage))?> LIVE SCREEN CONTROL</div><h1 class="h2 mb-1"><?=e($round['event_name'])?></h1><div class="text-muted"><?=e(ucwords(str_replace('_',' ',$round['division'])))?> · <?=e($stage)?></div></div><?php endif;?><div class="card shadow-sm mb-4"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">Projector Live Feed Link</h2><?php if($displayUrl):?><span class="small text-success"><span class="status-dot"></span>Live link ready</span><?php endif;?></div><?php if($displayUrl):?><div class="input-group mt-3"><input id="liveUrl" class="form-control" readonly value="<?=e($displayUrl)?>"><button type="button" class="btn btn-outline-primary" onclick="navigator.clipboard.writeText(liveUrl.value)">Copy Link</button><a target="_blank" class="btn btn-primary" href="<?=e($displayUrl)?>">Open Preview</a></div><?php else:?><p class="text-muted mt-2">Generate one link. The projector operator opens it once and leaves it full-screen.</p><?php endif;?><form method="post" class="mt-2"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="embed" value="<?=$embed?'1':'0'?>"><button class="btn btn-dark" name="action" value="generate_live">Generate / Regenerate Live Display Link</button></form></div></div><form class="card settings shadow-sm mb-4" method="post" action="settings.php"><div class="card-body"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="data_mode" value="real"><input type="hidden" name="embed" value="<?=$embed?'1':'0'?>"><h2 class="h5">Screen & Layout</h2><div class="row g-2"><div class="col-md-4"><label class="form-label">Screen Format</label><select id="format" name="screen_format" class="form-select"><?php foreach($formats as $v=>$l):?><option value="<?=e($v)?>" <?=$settings['screen_format']===$v?'selected':''?>><?=e($l)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Density</label><select name="density" class="form-select"><option value="maximum" <?=$settings['density']==='maximum'?'selected':''?>>Maximum Density</option><option value="auto" <?=$settings['density']==='auto'?'selected':''?>>Auto</option><option value="large" <?=$settings['density']==='large'?'selected':''?>>Large Cards</option></select></div><div class="col-md-2"><label class="form-label">Custom Width</label><input id="cw" name="custom_width" class="form-control" type="number" min="100" value="<?=e((string)($settings['custom_width']??''))?>"></div><div class="col-md-2"><label class="form-label">Custom Height</label><input id="ch" name="custom_height" class="form-control" type="number" min="100" value="<?=e((string)($settings['custom_height']??''))?>"></div></div><div class="d-flex gap-2 mt-3"><button class="btn btn-danger" name="action" value="apply">Apply Screen Settings</button><button class="btn btn-outline-secondary" name="action" value="reset">Reset to 16:9</button></div></div></form><div class="card shadow-sm"><div class="card-body"><input type="hidden" id="csrf" value="<?=e(Csrf::token())?>"><h2 class="h5">Live Feed Remote Control</h2><div id="remoteMessage" class="small mb-2 text-muted">Click a feed and the projector screen will update automatically.</div><div class="d-flex flex-wrap gap-2 mb-3"><button type="button" class="feed btn btn-outline-dark" data-screen="holding">Holding Screen</button><?php foreach($types as $v=>$l):$protected=in_array($v,['results','winners'],true);?><button type="button" class="feed btn <?=($session['screen_type']??'')===$v?'btn-danger':'btn-outline-danger'?> <?=$protected&&empty($session['results_unlocked'])?'locked':''?>" data-screen="<?=e($v)?>" data-protected="<?=$protected?'1':'0'?>" <?=$protected&&empty($session['results_unlocked'])?'disabled':''?>><?=$protected&&empty($session['results_unlocked'])?'🔒 ':''?><?=e($l)?></button><?php endforeach;?></div><?php if($round['round_type']==='final'):?><div class="border rounded p-3 mb-3 bg-light"><div class="fw-bold">Results Reveal Safety</div><div class="small text-muted mb-2">Final Ranking and Winner Podium are locked to prevent accidental public reveal.</div><button type="button" id="unlockResults" class="btn <?=!empty($session['results_unlocked'])?'btn-success':'btn-warning'?> btn-sm"><?=!empty($session['results_unlocked'])?'Results Reveal Unlocked':'Unlock Results Reveal'?></button><button type="button" id="lockResults" class="btn btn-outline-secondary btn-sm ms-2" <?=empty($session['results_unlocked'])?'disabled':''?>>Lock</button></div><?php endif;?><div class="row g-2"><div class="col-md-3"><label class="form-label">Page</label><input id="pageNumber" class="form-control" type="number" min="1" value="<?=(int)($session['page_number']??1)?>"></div><div class="col-md-3"><label class="form-label">Auto Page</label><select id="autoPage" class="form-select"><option value="1" <?=!isset($session['auto_page'])||$session['auto_page']?'selected':''?>>On</option><option value="0" <?=isset($session['auto_page'])&&!$session['auto_page']?'selected':''?>>Off</option></select></div><div class="col-md-3"><label class="form-label">Page Delay</label><select id="pageDelay" class="form-select"><?php foreach([10,15,30,45,60] as $d):?><option value="<?=$d?>" <?=($session['page_delay_seconds']??30)===$d?'selected':''?>><?=$d?> seconds</option><?php endforeach;?></select></div></div><div class="small text-muted mt-2">Auto Page defaults to 30 seconds and applies to multi-page Competitors, Callbacks and Finalists.</div></div></div></main><script>const eventId=<?=$eventId?>,roundId=<?=$roundId?>,csrf=document.querySelector('#csrf').value,msg=document.querySelector('#remoteMessage');let resultsUnlocked=<?=!empty($session['results_unlocked'])?'true':'false'?>;async function postAction(data){const body=new URLSearchParams({_csrf:csrf,event_id:eventId,round_id:roundId,data_mode:'real',page_number:pageNumber.value,auto_page:autoPage.value,page_delay_seconds:pageDelay.value,...data});const r=await fetch('live-action.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const j=await r.json();if(!j.ok)throw new Error(j.error||'Update failed');return j}function paint(j){if(j.session){resultsUnlocked=!!j.session.results_unlocked;document.querySelectorAll('.feed').forEach(b=>{const active=b.dataset.screen===j.session.screen_type;if(b.dataset.screen!=='holding'){b.classList.toggle('btn-danger',active);b.classList.toggle('btn-outline-danger',!active)}});syncLock()}msg.className='small mb-2 text-success';msg.textContent='Projector updated.'}function syncLock(){document.querySelectorAll('[data-protected="1"]').forEach(b=>{b.disabled=!resultsUnlocked;b.classList.toggle('locked',!resultsUnlocked);const raw=b.textContent.replace(/^🔒\s*/,'');b.textContent=(resultsUnlocked?'':'🔒 ')+raw});const u=document.querySelector('#unlockResults'),l=document.querySelector('#lockResults');if(u){u.textContent=resultsUnlocked?'Results Reveal Unlocked':'Unlock Results Reveal';u.className='btn '+(resultsUnlocked?'btn-success':'btn-warning')+' btn-sm';l.disabled=!resultsUnlocked}}document.querySelectorAll('.feed').forEach(b=>b.onclick=async()=>{try{msg.className='small mb-2 text-muted';msg.textContent='Updating projector…';paint(await postAction({action:'update',screen_type:b.dataset.screen}))}catch(e){msg.className='small mb-2 text-danger';msg.textContent=e.message}});const unlock=document.querySelector('#unlockResults');if(unlock)unlock.onclick=async()=>{if(resultsUnlocked)return;if(!confirm('This can reveal official competition results on the live projector. Continue?'))return;try{paint(await postAction({action:'unlock_results'}))}catch(e){alert(e.message)}};const lock=document.querySelector('#lockResults');if(lock)lock.onclick=async()=>{try{paint(await postAction({action:'lock_results'}))}catch(e){alert(e.message)}};function cs(){const on=document.querySelector('#format').value==='custom';cw.disabled=!on;ch.disabled=!on}format.addEventListener('change',cs);cs();<?php if($embed):?>function report(){parent.postMessage({type:'bdc-control-height',height:document.documentElement.scrollHeight},'*')}new ResizeObserver(report).observe(document.body);window.addEventListener('load',report);<?php endif;?></script></body></html>